-- Hand-written: invoice status flow, void pairing, currency, type and parent checks, milestone scope (M5.1), generated by scripts/write-triggers.ts from src/triggers.ts.
CREATE TRIGGER `documents_invoice_status_flow` BEFORE UPDATE OF status ON `documents` WHEN NEW.status IS NOT OLD.status AND OLD.type IN ('proforma', 'tax_invoice', 'export_invoice', 'credit_note', 'debit_note') AND NOT ((OLD.status = 'draft' AND NEW.status IN ('issued')) OR (OLD.status = 'issued' AND NEW.status IN ('void') AND NEW.paid_minor = 0 AND OLD.paid_minor = 0 AND NEW.credited_minor = 0 AND OLD.credited_minor = 0 AND NOT EXISTS (SELECT 1 FROM documents c WHERE c.parent_id = OLD.id AND c.frozen_at IS NOT NULL)) OR (OLD.status = 'issued' AND NEW.status IN ('partially_paid', 'paid', 'partially_credited', 'credited')) OR (OLD.status = 'partially_paid' AND NEW.status IN ('issued', 'paid', 'partially_credited', 'credited')) OR (OLD.status = 'paid' AND NEW.status IN ('issued', 'partially_paid', 'partially_credited', 'credited')) OR (OLD.status = 'partially_credited' AND NEW.status IN ('issued', 'partially_paid', 'paid', 'credited')) OR (OLD.status = 'credited' AND NEW.status IN ('issued', 'partially_paid', 'paid', 'partially_credited')) OR (OLD.status = 'issued' AND NEW.status IN ('converted') AND OLD.type IN ('proforma')) OR (OLD.status = 'partially_paid' AND NEW.status IN ('converted') AND OLD.type IN ('proforma')) OR (OLD.status = 'paid' AND NEW.status IN ('converted') AND OLD.type IN ('proforma'))) BEGIN SELECT RAISE(ABORT, 'documents_invoice_status_flow: that status change is not allowed'); END;
--> statement-breakpoint
CREATE TRIGGER `documents_void_pairing` BEFORE UPDATE OF status, voided_at, void_reason ON `documents` WHEN NEW.type IN ('proforma', 'tax_invoice', 'export_invoice', 'credit_note', 'debit_note') AND OLD.status <> 'void' AND ((NEW.status = 'void' AND (NEW.voided_at IS NULL OR NEW.void_reason IS NULL OR NEW.frozen_at IS NULL)) OR (NEW.status <> 'void' AND NEW.voided_at IS NOT NULL)) BEGIN SELECT RAISE(ABORT, 'documents_void_pairing: a void document has its time and reason, and only an issued document can be void'); END;
--> statement-breakpoint
CREATE TRIGGER `documents_invoice_currency_insert` BEFORE INSERT ON `documents` WHEN NEW.type IN ('proforma', 'tax_invoice', 'export_invoice', 'credit_note', 'debit_note', 'receipt', 'receipt_voucher', 'refund_voucher') AND NEW.currency IS NOT (SELECT currency FROM clients WHERE id = NEW.client_id) BEGIN SELECT RAISE(ABORT, 'documents_invoice_currency: an invoice has the currency of its client'); END;
