CREATE TRIGGER `documents_invoice_currency_update` BEFORE UPDATE OF type, currency, client_id ON `documents` WHEN OLD.frozen_at IS NULL AND NEW.type IN ('proforma', 'tax_invoice', 'export_invoice', 'credit_note', 'debit_note', 'receipt', 'receipt_voucher', 'refund_voucher') AND NEW.currency IS NOT (SELECT currency FROM clients WHERE id = NEW.client_id) BEGIN SELECT RAISE(ABORT, 'documents_invoice_currency: an invoice has the currency of its client'); END;
--> statement-breakpoint
CREATE TRIGGER `documents_invoice_type_client_insert` BEFORE INSERT ON `documents` WHEN (NEW.type = 'export_invoice' AND (SELECT gst_status FROM clients WHERE id = NEW.client_id) IS NOT 'overseas') OR (NEW.type = 'tax_invoice' AND (SELECT gst_status FROM clients WHERE id = NEW.client_id) IS 'overseas') BEGIN SELECT RAISE(ABORT, 'documents_invoice_type_client: an export invoice is for an overseas client and a tax invoice for a client in India'); END;
