CREATE TRIGGER `documents_parent_check_update` BEFORE UPDATE OF parent_id, type, client_id ON `documents` WHEN OLD.frozen_at IS NULL AND NEW.parent_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM documents p WHERE p.id = NEW.parent_id AND p.frozen_at IS NOT NULL AND p.client_id = NEW.client_id AND ((NEW.type IN ('credit_note', 'debit_note') AND p.type IN ('tax_invoice', 'export_invoice')) OR (NEW.type IN ('tax_invoice', 'export_invoice') AND p.type = 'proforma') OR (NEW.type = 'receipt' AND p.type IN ('proforma', 'tax_invoice', 'export_invoice', 'credit_note', 'debit_note')))) BEGIN SELECT RAISE(ABORT, 'documents_parent_check: the parent must be an issued document of the same client in an allowed pair'); END;
