CREATE TRIGGER `milestones_document_scope` BEFORE UPDATE OF document_id ON `milestones` WHEN NEW.document_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM documents d WHERE d.id = NEW.document_id AND d.type IN ('proforma', 'tax_invoice', 'export_invoice', 'credit_note', 'debit_note', 'receipt', 'receipt_voucher', 'refund_voucher') AND d.client_id = (SELECT client_id FROM projects WHERE id = NEW.project_id)) BEGIN SELECT RAISE(ABORT, 'milestones_document_scope: the document of a milestone must be an invoice of the same client'); END;
